jQuery(document).ready(function($){var currentPage=1;var postsPerPage=9;function displayPosts(posts){var blogList=$('#blog-list');blogList.empty();$.each(posts,function(index,post){var postDiv=$('<div class="post">');postDiv.append('<a href="'+post.link+'"><div class="articlepostthumbnailurl"><img src="'+post.thumbnail+'"/></div></a>');postDiv.append('<div class="innerpost_wrapper"><div class="authorwrapper"><div class="postcategory">'+post.author+'</div><div class="postdate">'+post.date+'</div></div><div class="postlistingwrap"><a href="'+post.link+'"><h2>'+post.title+'</h2></a></div><div class="bloglistingfooterwrap"><div class="link"><a href="'+post.link+'"><i class="fa fa-arrow-right"></i></a></div></div></div>');blogList.append(postDiv)})}
function paginatePosts(){var pagination=$('#pagination');pagination.empty();$.ajax({url:ajax_object.ajax_url,type:'POST',data:{'action':'get_blog_posts','category':$('.category-btn.active').data('category'),'page':currentPage,'posts_per_page':postsPerPage},success:function(response){displayPosts(response.posts);pagination.html(response.pagination);$('.page-numbers').click(function(e){e.preventDefault();currentPage=parseInt($(this).text());paginatePosts()})}})}
function filterPosts(category){$('.category-btn').removeClass('active');$('.category-btn[data-category="'+category+'"]').addClass('active');currentPage=1;paginatePosts()}
$('.category-btn').click(function(){var category=$(this).data('category');filterPosts(category)});filterPosts('all')})